                        xlabel=$x$,
                        ylabel=$y$,
                        xmin=-4.2,
                        xmax=4.2,
                        axis x line*=bottom,
                        axis y line*=left,
                        xtick align=outside,
                        ytick align=outside,
                        legend pos=outer north east
                        ]
                        \addplot[mark=none, gray] {x^2};\addlegendentry{$y=x^2$}
                        \addplot[only marks, mark=*]
                        coordinates{ % plot 1 data set
                            (%s,%s)
                            }; 



                        \end{axis}

                \end{tikzpicture}
            \end{adjustbox}
        \end{column}
    \begin{column}{0.5\textwidth}
    \begin{adjustbox}{max totalsize={\textwidth},center}
        \begin{tikzpicture}
        \begin{axis}
        [
        title={Contour plot, view from top},
        view={0}{90},
        xlabel=$x$,
        ylabel=$y$,
        axis x line*=bottom,
        axis y line*=left,
        xtick align=outside,
        ytick align=outside,
        unit vector ratio*=1 1 1,
        ]
        \addplot3[
        contour gnuplot={number=14,}
        ]
        {x^2};
        \addplot[only marks, mark=*]
        coordinates{ % plot 1 data set
            (%f,%f)
        }; 
        \end{axis}
        \end{tikzpicture}
        \end{adjustbox}
    \end{column}
    \end{columns}


    \end{frame}
    """ %(i, i, i, i, i)

